def _prize_dep(dep_id, zh, en, glyph, accent, intro_zh, intro_en, entries, prefix):
    topics = []
    for year, who, tzh, ten, fzh, fen in entries:
        topics.append(T(f"{prefix}{year}", f"{year}｜{tzh}", f"{year} · {ten}", "prize",
                        f"得主：{who}。{fzh}", f"Laureates: {who}. {fen}", year=year, laureates=who,
                        flagship=year in (1923, 1945, 1962, 1979, 2003, 2015, 2018, 2020, 2023, 2024, 2025, 2026)))
    return D(dep_id, zh, en, "nobel", glyph, accent, intro_zh, intro_en, topics)

